import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"github Tag","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"slug":"github","tag":"github","title":"github Tag","prev":null,"next":"/tags/github/page/2/","posts":[{"title":"Git 提交规范","url":"/posts/2022-07-23-git-commit-lint/","date":"2022-07-23 20:37","tags":["github"],"html":"<p>良好的代码风格很重要，但是良好的 commit 记录同样重要。我们提交代码的时候都要提交 commit message，否则就不允许提交。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> commit</span><span style=\\"color:#005CC5\\"> -m</span><span style=\\"color:#032F62\\"> \\"hello world\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h2 id=\\"commit-message-格式\\" tabindex=\\"-1\\">commit message 格式 <a class=\\"header-anchor\\" href=\\"#commit-message-格式\\" aria-label=\\"Permalink to &quot;commit message 格式&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>目前最流行的提交规范是<a href=\\"https://www.conventionalcommits.org/en/v1.0.0/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Conventional Commits</a>，格式如下：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>&#x3C;type>[optional scope]: &#x3C;description></span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>[optional body]</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>[optional footer(s)]</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br></div></div><h3 id=\\"header\\" tabindex=\\"-1\\">Header <a class=\\"header-anchor\\" href=\\"#header\\" aria-label=\\"Permalink to &quot;Header&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>Header 有三个字段，type(必须)，scope(可选) 和 description(必须)。</p>\\n<p>type 用于说明 commit 的类别，有以下几个选项：build, chore, ci, docs, feat, fix, perf, refactor, revert, style, test</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>build: 对构建系统或者外部依赖项进行了修改</span></span>\\n<span class=\\"line\\"><span>chore: 构建过程或辅助工具的变动</span></span>\\n<span class=\\"line\\"><span>ci: 对CI配置文件或脚本进行了修改</span></span>\\n<span class=\\"line\\"><span>docs: 对文档进行了修改</span></span>\\n<span class=\\"line\\"><span>feat: 增加新功能</span></span>\\n<span class=\\"line\\"><span>fix: 修复BUG</span></span>\\n<span class=\\"line\\"><span>perf: 优化相关，比如提升性能，体验</span></span>\\n<span class=\\"line\\"><span>refactor: 重构代码</span></span>\\n<span class=\\"line\\"><span>revert: 回滚到上一个版本</span></span>\\n<span class=\\"line\\"><span>style: 修改代码格式</span></span>\\n<span class=\\"line\\"><span>test: 添加测试代码</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br></div></div><p>scope 用于说明 commit 影响的范围，比如某个组件的修改。</p>\\n<p>description 是 commit 目的的简短描述，不超过 50 个字符。最好以动词开头，首字母小写，末尾不加句号(.)</p>\\n<h3 id=\\"body\\" tabindex=\\"-1\\">Body <a class=\\"header-anchor\\" href=\\"#body\\" aria-label=\\"Permalink to &quot;Body&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>Body 是可选的，用来对本次提交进行详细描述， 可以写成多行，例如：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>fix: prevent racing of requests</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>Introduce a request id and a reference to latest request. Dismiss</span></span>\\n<span class=\\"line\\"><span>incoming responses other than from latest request.</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><h3 id=\\"footer\\" tabindex=\\"-1\\">Footer <a class=\\"header-anchor\\" href=\\"#footer\\" aria-label=\\"Permalink to &quot;Footer&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>Footer 也是可选的，主要有两个使用情况。一种是不兼容性更新：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>chore!: drop support for Node 6</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>BREAKING CHANGE: use JavaScript features not available in Node 6.</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>一种是引用提交的问题，例如本次提交是修正某个 Issue 的问题。</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>feat(lang): add Polish language</span></span>\\n<span class=\\"line\\"><span></span></span>\\n<span class=\\"line\\"><span>Closes #234</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>良好的 commit 提交规范和代码规范同样重要。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://www.ruanyifeng.com/blog/2016/01/commit_message_change_log.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Commit message 和 Change log 编写指南</a></p>\\n"},{"title":"Github 存储大文件","url":"/posts/2022-02-10-github-lfs/","date":"2022-02-10 23:16","tags":["github"],"html":"<p>最近在做项目的时候，需要上传一个超过 200MB 的数据库文件到 Github 上保存，结果 Github 提示文件过大。这才知道 Github 对单文件有 100 MB 的容量限制。</p>\\n<h2 id=\\"问题介绍\\" tabindex=\\"-1\\">问题介绍 <a class=\\"header-anchor\\" href=\\"#问题介绍\\" aria-label=\\"Permalink to &quot;问题介绍&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>正常情况下，我们执行 add, commit 操作的时候都没啥问题。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> .</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> commit</span><span style=\\"color:#005CC5\\"> -m</span><span style=\\"color:#032F62\\"> \\"add large file\\"</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>但是执行 push 操作的时候会返回错误。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> push</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Enumerating</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 21,</span><span style=\\"color:#032F62\\"> done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Counting</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (21/21), done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Delta</span><span style=\\"color:#032F62\\"> compression</span><span style=\\"color:#032F62\\"> using</span><span style=\\"color:#032F62\\"> up</span><span style=\\"color:#032F62\\"> to</span><span style=\\"color:#005CC5\\"> 10</span><span style=\\"color:#032F62\\"> threads</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Compressing</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (17/17), done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Writing</span><span style=\\"color:#032F62\\"> objects:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (17/17), 153.95 MiB </span><span style=\\"color:#D73A49\\">|</span><span style=\\"color:#6F42C1\\"> 13.82</span><span style=\\"color:#032F62\\"> MiB/s,</span><span style=\\"color:#032F62\\"> done.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Total</span><span style=\\"color:#005CC5\\"> 17</span><span style=\\"color:#24292E\\"> (delta </span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">), reused 0 (</span><span style=\\"color:#6F42C1\\">delta</span><span style=\\"color:#005CC5\\"> 0</span><span style=\\"color:#24292E\\">), pack-reused 0</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> Resolving</span><span style=\\"color:#032F62\\"> deltas:</span><span style=\\"color:#032F62\\"> 100%</span><span style=\\"color:#24292E\\"> (4/4), completed with 3 </span><span style=\\"color:#D73A49\\">local</span><span style=\\"color:#24292E\\"> objects.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> error:</span><span style=\\"color:#032F62\\"> Trace:</span><span style=\\"color:#6A737D\\"> ###</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> error:</span><span style=\\"color:#032F62\\"> See</span><span style=\\"color:#032F62\\"> http://git.io/iEPt8g</span><span style=\\"color:#032F62\\"> for</span><span style=\\"color:#032F62\\"> more</span><span style=\\"color:#032F62\\"> information.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">remote:</span><span style=\\"color:#032F62\\"> error:</span><span style=\\"color:#032F62\\"> File</span><span style=\\"color:#032F62\\"> xxx.db</span><span style=\\"color:#032F62\\"> is</span><span style=\\"color:#005CC5\\"> 259.50</span><span style=\\"color:#032F62\\"> MB</span><span style=\\"color:#24292E\\">; </span><span style=\\"color:#6F42C1\\">this</span><span style=\\"color:#032F62\\"> exceeds</span><span style=\\"color:#032F62\\"> GitHub\'s file size limit of 100.00 MB</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">remote: error: GH001: Large files detected. You may want to try Git Large File Storage - https://git-lfs.github.com.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">To https://github.com/acgotaku/switch.git</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\"> ! [remote rejected] master -> master (pre-receive hook declined)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">error: failed to push some refs to \'https://github.com/{user}/{repo}.git\'</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br></div></div><p>这里提示我们可以使用 Git Large File Storage 来解决。</p>\\n<h2 id=\\"安装-lfs\\" tabindex=\\"-1\\">安装 LFS <a class=\\"header-anchor\\" href=\\"#安装-lfs\\" aria-label=\\"Permalink to &quot;安装 LFS&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>根据官网的教程进行安装：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> brew</span><span style=\\"color:#032F62\\"> install</span><span style=\\"color:#032F62\\"> git-lfs</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>然后 cd 到对应的 repo：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> cd</span><span style=\\"color:#032F62\\"> {repo}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> lfs</span><span style=\\"color:#032F62\\"> install</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Updated</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> hooks.</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Git</span><span style=\\"color:#032F62\\"> LFS</span><span style=\\"color:#032F62\\"> initialized.</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br></div></div><h2 id=\\"重新提交\\" tabindex=\\"-1\\">重新提交 <a class=\\"header-anchor\\" href=\\"#重新提交\\" aria-label=\\"Permalink to &quot;重新提交&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>这时候我们需要保留文件的同时，取消 commit：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> cd</span><span style=\\"color:#032F62\\"> {REPO}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> reset</span><span style=\\"color:#005CC5\\"> --soft</span><span style=\\"color:#032F62\\"> HEAD^</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>然后单独提交大文件：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> lfs</span><span style=\\"color:#032F62\\"> track</span><span style=\\"color:#032F62\\"> {LARGE_FILE}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">Tracking</span><span style=\\"color:#032F62\\"> {LARGE_FILE}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> .gitattributes</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><p>执行第一行命令之后会生成一个 <code>.gitattributes</code> 文件，记得这个也需要一并提交。</p>\\n<p>接下来执行普通的 add commit, push 三个步骤就可以了。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> .</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> commit</span><span style=\\"color:#005CC5\\"> -m</span><span style=\\"color:#032F62\\"> \\"add large file\\"</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">$</span><span style=\\"color:#032F62\\"> git</span><span style=\\"color:#032F62\\"> push</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>Github 针对大文件存储有一个月 1GB 流量的限制，所以如果到达限制了需要付费才能继续使用。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://qiita.com/kanaya/items/ad52f25da32cb5aa19e6\\" target=\\"_blank\\" rel=\\"noreferrer\\">GitHub に 100MB 超のファイルを置く</a></p>\\n"},{"title":"Github如何省略每次输入验证信息","url":"/posts/2019-06-23-github-omit-auth/","date":"2019-06-23 20:21","tags":["github"],"html":"<p>项目开发中经常会遇到 CI 自动拉取 Github 库的情况，我们个人使用的时候会手动输入账户密码信息，但是针对 CI 来说，我们一般会把敏感的认证信息放在环境变量里。所以针对认证信息的自动输入，需要做一些处理。</p>\\n<h2 id=\\"环境变量自动替换\\" tabindex=\\"-1\\">环境变量自动替换 <a class=\\"header-anchor\\" href=\\"#环境变量自动替换\\" aria-label=\\"Permalink to &quot;环境变量自动替换&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>针对 Travis CI，我们一般把认证信息放在环境变量里，所以在执行 clone 其他 repo 的时候，可以先设置认证信息。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">git</span><span style=\\"color:#032F62\\"> config</span><span style=\\"color:#005CC5\\"> --global</span><span style=\\"color:#032F62\\"> url.\\"https://${</span><span style=\\"color:#24292E\\">CI_USER_NAME</span><span style=\\"color:#032F62\\">}:${</span><span style=\\"color:#24292E\\">CI_USER_TOKEN</span><span style=\\"color:#032F62\\">}@github.com/\\".insteadOf</span><span style=\\"color:#032F62\\"> \\"https://github.com/\\"\'</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这样设置的话，会自动替换 git clone 的网址。</p>\\n<h2 id=\\"url-里面写入认证信息\\" tabindex=\\"-1\\">URL 里面写入认证信息 <a class=\\"header-anchor\\" href=\\"#url-里面写入认证信息\\" aria-label=\\"Permalink to &quot;URL 里面写入认证信息&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>有时候需要以另外一个身份进行 clone repo 的时候，会直接在 repo 的 URL 前面加上认证信息。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">git</span><span style=\\"color:#032F62\\"> clone</span><span style=\\"color:#032F62\\"> https://</span><span style=\\"color:#24292E\\">${USER_NAME}</span><span style=\\"color:#032F62\\">:</span><span style=\\"color:#24292E\\">${USER_TOKEN}</span><span style=\\"color:#032F62\\">@github.com/{username}/{repo}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这样可以很方便的 clone 信息，但是认证信息会存在当前库的 git config 文件里，有泄漏的风险。</p>\\n<h2 id=\\"netrc-设置\\" tabindex=\\"-1\\">netrc 设置 <a class=\\"header-anchor\\" href=\\"#netrc-设置\\" aria-label=\\"Permalink to &quot;netrc 设置&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>netr 文件用于存储网站的认证信息，一般位置在<code>~/.netrc</code>。格式是：</p>\\n<div class=\\"language- line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\"></span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span>machine github.com</span></span>\\n<span class=\\"line\\"><span>login username</span></span>\\n<span class=\\"line\\"><span>password xxxxxxx</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br></div></div><h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>总共有这么三种省略认证信息的方式，根据实际情况选择自己方便的一种认证方式即可。</p>\\n<p>参考：</p>\\n<p><a href=\\"https://qiita.com/azusanakano/items/8dc1d7e384b00239d4d9\\" target=\\"_blank\\" rel=\\"noreferrer\\">GitHub でユーザ名・パスワード省略</a></p>\\n"}]},"relativePath":"tags/github/index.md","filePath":"tags/[slug].md"}'),e={name:"tags/github/index.md"};function p(l,o,r,t,i,c){return a(),n("div")}const u=s(e,[["render",p]]);export{b as __pageData,u as default};
